sql.content:

select top %(pagesize)s o.* from ( select row_number() over(order by %(orderby)s) as rownumber, * from (
    %(sql)s
) oo) o where o.rownumber>%(firstindex)s


select * from ( select ROWNUM rownumber, o.* from (
    %(sql)s   order by %(orderby)s
) o) where rownumber<=(%(firstindex)s + %(pagesize)s) and rownumber>%(firstindex)s
